import{_ as i,o as u,c as t,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Ushughulikiaji wa Tawi Nne za Mwili wa Uingizwaji wa Giza","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0059-黑暗置换体四类分支处置.md","filePath":"sw/0059-黑暗置换体四类分支处置.md"}'),h={name:"sw/0059-黑暗置换体四类分支处置.md"};function k(w,a,o,e,d,l){return u(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="ushughulikiaji-wa-tawi-nne-za-mwili-wa-uingizwaji-wa-giza" tabindex="-1">Ushughulikiaji wa Tawi Nne za Mwili wa Uingizwaji wa Giza <a class="header-anchor" href="#ushughulikiaji-wa-tawi-nne-za-mwili-wa-uingizwaji-wa-giza" aria-label="Permalink to &quot;Ushughulikiaji wa Tawi Nne za Mwili wa Uingizwaji wa Giza&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>59</td></tr><tr><td>Moduli</td><td>Kabila na Aina za Uhai</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Uunganishaji wa ushirika, Uingizwaji wa kutengana, Ufungaji wa ufuatiliaji, Uharibifu, Ushughulikiaji wa tawi</td></tr></tbody></table><h2 id="_1-muundo-wa-jumla-wa-ushughulikiaji-wa-tawi" tabindex="-1">1. Muundo wa Jumla wa Ushughulikiaji wa Tawi <a class="header-anchor" href="#_1-muundo-wa-jumla-wa-ushughulikiaji-wa-tawi" aria-label="Permalink to &quot;1. Muundo wa Jumla wa Ushughulikiaji wa Tawi&quot;">​</a></h2><p>Ushughulikiaji wa mwili wa uingizwaji wa giza ndio uwanja mgumu zaidi katika utawala wa uhai wa ustaarabu wa ushirika wa nanga. Tofauti na mchakato wa ushughulikiaji wa aina tatu za uhai wa ajabu na nishati ya ajabu, mwili wa uingizwaji wa giza kwa sababu inahusisha muundo maalum wa kuishi pamoja kwa roho mbili (tazama maelezo ya &quot;57-Asili na Hali ya Kweli ya Mwili wa Uingizwaji wa Giza&quot;), inahitaji mpango wa ushughulikiaji wa tawi ulio bora zaidi. Kulingana na kanuni za kimaadili zilizowekwa na &quot;58-Kanuni za Kimaadili za Roho Mbili&quot;, pamoja na hatua ya maendeleo ya mwili wa uingizwaji wa giza, hali ya roho ya mwenyeji asili, sifa za roho ya giza na kiwango cha hatari, ushughulikiaji wa mwili wa uingizwaji wa giza umegawanywa katika tawi nne: aina ya uunganishaji wa ushirika, aina ya uingizwaji wa kutengana, aina ya ufungaji wa ufuatiliaji, aina ya uharibifu.</p><p>Uchaguzi wa ushughulikiaji wa tawi nune unafuata mantiki ya uamuzi ifuatayo:</p><table tabindex="0"><thead><tr><th>Kipengele cha Uamuzi</th><th>Mazingatio</th></tr></thead><tbody><tr><td>Hatua ya Maendeleo</td><td>Kutoka hatua ya kwanza hadi ya tatu inapendelea uokoaji, hatua ya nne inachunguzwa kwa uangalifu, hatua ya tano mwenyeji asili amekufa tayari</td></tr><tr><td>Hali ya Roho ya Mwenyeji Asili</td><td>Je roho ya mwenyeji asili bado ipo, je inaweza kuonyesha mapenzi, je ina uwezo wa kupona</td></tr><tr><td>Sifa za Roho ya Giza</td><td>Je roho ya giza ina uwezo wa mawasiliano, je ina nafasi ya marekebisho, kiwango cha uharibifu</td></tr><tr><td>Kiwango cha Hatari</td><td>Kiwango cha tishio kwa usalama wa umma na haki za wengine</td></tr><tr><td>Hitimisho ya Hakiki ya Kimaadili</td><td>Maoni ya hakiki na uamuzi wa kamati ya hakiki ya kimaadili ya roho mbili</td></tr><tr><td>Mapenzi ya Mwenyeji Asili</td><td>Uchaguzi wa roho ya mwenyeji asili katika hali ya kuweza kuonyesha mapenzi</td></tr></tbody></table><h2 id="_2-aina-ya-kwanza-ushughulikiaji-wa-aina-ya-uunganishaji-wa-ushirika" tabindex="-1">2. Aina ya Kwanza: Ushughulikiaji wa Aina ya Uunganishaji wa Ushirika <a class="header-anchor" href="#_2-aina-ya-kwanza-ushughulikiaji-wa-aina-ya-uunganishaji-wa-ushirika" aria-label="Permalink to &quot;2. Aina ya Kwanza: Ushughulikiaji wa Aina ya Uunganishaji wa Ushirika&quot;">​</a></h2><p>Ushughulikiaji wa aina ya uunganishaji wa ushirika ndio njia ya ushughulikiaji yenye shughuli zaidi na yenye ujenzi zaidi kati ya tawi nne, inatumika kwa miili ya uingizwaji wa giza ambapo roho ya mwenyeji asili na roho ya giza zina uwezo wa kufikia makubaliano na kutekeleza uunganishaji wa roho.</p><h3 id="_1-masharti-ya-matumizi" tabindex="-1">(1) Masharti ya Matumizi <a class="header-anchor" href="#_1-masharti-ya-matumizi" aria-label="Permalink to &quot;(1) Masharti ya Matumizi&quot;">​</a></h3><p>Ushughulikiaji wa aina ya uunganishaji wa ushirika lazima kwa wakati mmoja ukidhi masharti yafuatayo:</p><ol><li>Mwili wa uingizwaji wa giza uko katika hatua ya tatu (kipindi cha uundaji wa roho mbili) au mwanzo wa hatua ya nne (mwanzo wa kipindi cha utawala wa giza), roho ya mwenyeji asili bado ipo na ina fahamu ya kujitegemea fulani.</li><li>Roho ya mwenyeji asili imetaja wazi mapenzi ya kujaribu uunganishaji na roho ya giza, na mapenzi hayo yametambuliwa kuwa ya kweli na ya kujitegemea.</li><li>Roho ya giza ina uwezo fulani wa mawasiliano, inaonyesha sifa zisizo za uharibifu kabisa, ina uwezo wa kukubali uunganishaji.</li><li>Tathmini ya kiwango cha hatari ni kiwango cha pili (hatari ya wastani) au chini yake, mchakato wa uunganishaji hautakuwa tishio lisilodhibitika kwa usalama wa umma.</li><li>Imekubaliwa na kamati ya hakiki ya kimaadili ya roho mbili.</li></ol><h3 id="_2-lengo-la-ushughulikiaji" tabindex="-1">(2) Lengo la Ushughulikiaji <a class="header-anchor" href="#_2-lengo-la-ushughulikiaji" aria-label="Permalink to &quot;(2) Lengo la Ushughulikiaji&quot;">​</a></h3><p>Kupitia mwongozo wa roho ya mwenyeji asili na roho ya giza kufikia makubaliano, kutekeleza uunganishaji wa kikaboni wa roho mbili, kuunda roho mpya inayochanganya kumbukumbu, tabia ya mwenyeji asili na nguvu ya giza. Roho mpya baada ya uunganishaji inabaki na utambulisho wa raia na haki za kisheria za mwenyeji asili, wakati huo huo inapata uwezo wa kudhibiti nishati ya giza, na kuwa mwanachama maalum wa ustaarabu wa ushirika.</p><h3 id="_3-hatua-za-ushughulikiaji" tabindex="-1">(3) Hatua za Ushughulikiaji <a class="header-anchor" href="#_3-hatua-za-ushughulikiaji" aria-label="Permalink to &quot;(3) Hatua za Ushughulikiaji&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Maudhui Mahususi</th><th>Shirika Lenye Jukumu</th></tr></thead><tbody><tr><td>Hatua ya kwanza</td><td>Hakiki ya kimaadili</td><td>Kamati ya hakiki ya kimaadili ya roho mbili inafanya hakiki kamili ya mpango wa uunganishaji, inathibitisha kuwa inafuata kanuni za kimaadili</td><td>Kamati ya hakiki ya kimaadili ya roho mbili</td></tr><tr><td>Hatua ya pili</td><td>Mwongozo wa mawasiliano</td><td>Katika mazingira yaliyodhibitiwa, mshauri wa roho mtaalamu anasaidia roho ya mwenyeji asili na roho ya giza kuwasiliana, akukuza uelewano wa kubadilishana</td><td>Kituo cha Matibabu ya Roho + mtu anayefanya mazoezi</td></tr><tr><td>Hatua ya tatu</td><td>Mazungumzo ya makubaliano</td><td>Kuongoza roho mbili kufikia makubaliano ya suluhu kuhusu utambulisho, kumbukumbu, uwezo, sheria za tabia, n.k. baada ya uunganishaji</td><td>Kituo cha Matibabu ya Roho + mshauri wa kisheria</td></tr><tr><td>Hatua ya nne</td><td>Maandalizi ya uunganishaji</td><td>Kufanya kazi za maandalizi kabla ya uunganishaji kama vile marekebisho ya mwili, usawa wa nishati, ujenzi wa kisaikolojia, n.k.</td><td>Timu ya Matibabu + mshauri wa mazoezi</td></tr><tr><td>Hatua ya tano</td><td>Uunganishaji wa roho</td><td>Kupitia msaada wa pamoja wa watu wenye uwezo wa juu wa mazoezi na matibabu ya roho, kutekeleza upasuaji/heshima za uunganishaji wa roho</td><td>Watu wenye uwezo wa juu wa mazoezi + matibabu ya roho</td></tr><tr><td>Hatua ya sita</td><td>Uthabiti baada ya uunganishaji</td><td>Kufanya matibabu ya uthabiti kwa roho mpya baada ya uunganishaji, kufuatilia ukamilifu wa roho na uwezo wa kuzingatia mwili</td><td>Timu ya Matibabu + timu ya ufuatiliaji</td></tr><tr><td>Hatua ya saba</td><td>Uthibitisho wa utambulisho</td><td>Kuthibitisha utambulisho wa roho mpya baada ya uunganishaji, kubaki na utambulisho wa raia wa mwenyeji asili, kusasisha rekodi ya utambulisho</td><td>Shirika la Usimamizi wa Usajili + Ofisi ya Usimamizi wa Uhai</td></tr><tr><td>Hatua ya nane</td><td>Msaada wa ujumuishaji</td><td>Kutoa huduma za msaada kama vile ushauri wa kisaikolojia, mwongozo wa mazoezi, ujumuishaji wa kijamii, n.k. kwa mtu binafsi baada ya uunganishaji</td><td>Idara ya Masuala ya Kabila Zote + jamii</td></tr><tr><td>Hatua ya tisa</td><td>Ufuatiliaji wa muda mrefu</td><td>Kufanya ufuatiliaji wa muda mrefu usio chini ya miaka mitano kwa mtu aliyeunganishwa, kutathmini uthabiti wa uunganishaji na uwezo wa kuzingatia kijamii</td><td>Ofisi ya Usimamizi wa Uhai + jamii</td></tr></tbody></table><h3 id="_4-usimamizi-baada-ya-uunganishaji" tabindex="-1">(4) Usimamizi Baada ya Uunganishaji <a class="header-anchor" href="#_4-usimamizi-baada-ya-uunganishaji" aria-label="Permalink to &quot;(4) Usimamizi Baada ya Uunganishaji&quot;">​</a></h3><p>Ingawa mtu binafsi baada ya uunganishaji anabaki na utambulisho wa raia wa mwenyeji asili, anahitaji kukubali usimamizi maalum:</p><ul><li><strong>Udhibiti wa nishati</strong>: Matumizi ya nishati ya giza na mtu aliyeunganishwa yanadhibitiwa kwa mkali, lazima afanye uchunguzi wa nishati mara kwa mara, inakatazwa kutumia nishati ya giza katika sehemu za umma.</li><li><strong>Ufuatiliaji wa tabia</strong>: Mtu aliyeunganishwa lazima aripoti mara kwa mara hali ya tabia yake kwa Ofisi ya Usimamizi wa Uhai, akubali ufuatiliaji na msaada wa jamii.</li><li><strong>Vizuizi vya mazoezi</strong>: Mtu aliyeunganishwa hawezi kufanya mazoezi ya njia ambazo zinaweza kuongeza tabia ya giza, mpango wa mazoezi lazima upate idhini.</li><li><strong>Mpango wa dharura</strong>: Kuunda mpango wa dharura kwa upotezaji wa udhibiti wa giza wa mtu aliyeunganishwa, mara moja kuanzisha udhibiti mara tu dalili za upotezaji wa udhibiti zinaonekana.</li><li><strong>Mfumo wa kutokea</strong>: Iwapo baada ya uunganishaji kutokea uthabiti mbaya au tabia hatari inayoendelea, inaweza kutathminiwa upya na kubadilishwa kuwa ushughulikiaji wa aina nyingine.</li></ul><h3 id="_5-ushughulikiaji-wa-kushindwa-kwa-uunganishaji" tabindex="-1">(5) Ushughulikiaji wa Kushindwa kwa Uunganishaji <a class="header-anchor" href="#_5-ushughulikiaji-wa-kushindwa-kwa-uunganishaji" aria-label="Permalink to &quot;(5) Ushughulikiaji wa Kushindwa kwa Uunganishaji&quot;">​</a></h3><p>Uunganishaji wa roho una hatari ya kushindwa, mpango wa ushughulikiaji wa kushindwa kwa uunganishaji:</p><ul><li><strong>Kukatisha uunganishaji</strong>: Iwapo uthabiti mbaya unaonekana wakati wa mchakato wa uunganishaji, mara moja kukatisha uunganishaji, kurudisha roho mbili hadi hali kabla ya uunganishaji.</li><li><strong>Uunganishaji usio kamili</strong>: Iwapo baada ya uunganishaji kutokea ukosefu wa roho au mgawanyiko wa tabia, kubadilishwa kuwa ushughulikiaji wa aina ya uingizwaji wa kutengana kwa usindikaji wa baadaye.</li><li><strong>Uunganishaji uliopoteza udhibiti</strong>: Iwapo baada ya uunganishaji roho mpya inaonyesha uharibifu usiodhibitika, mara moja kubadilishwa kuwa ushughulikiaji wa aina ya ufungaji wa ufuatiliaji au aina ya uharibifu.</li></ul><h2 id="_3-aina-ya-pili-ushughulikiaji-wa-aina-ya-uingizwaji-wa-kutengana" tabindex="-1">3. Aina ya Pili: Ushughulikiaji wa Aina ya Uingizwaji wa Kutengana <a class="header-anchor" href="#_3-aina-ya-pili-ushughulikiaji-wa-aina-ya-uingizwaji-wa-kutengana" aria-label="Permalink to &quot;3. Aina ya Pili: Ushughulikiaji wa Aina ya Uingizwaji wa Kutengana&quot;">​</a></h2><p>Ushughulikiaji wa aina ya uingizwaji wa kutengana unatumika kwa miili ya uingizwaji wa giza ambapo roho ya mwenyeji asili na roho ya giza haziwezi kuunganishwa lakini zinaweza kutengana, kupitia upasuaji wa kutenganisha roho kutenganisha roho mbili, kuweka tofauti.</p><h3 id="_1-masharti-ya-matumizi-1" tabindex="-1">(1) Masharti ya Matumizi <a class="header-anchor" href="#_1-masharti-ya-matumizi-1" aria-label="Permalink to &quot;(1) Masharti ya Matumizi&quot;">​</a></h3><ol><li>Mwili wa uingizwaji wa giza uko katika hatua ya tatu au nne, roho ya mwenyeji asili bado ipo na ina uwezo wa kupona.</li><li>Juhudi za uunganishaji wa roho mbili zimeshindwa au hakuna masharti ya uunganishaji.</li><li>Tathmini ya kiufundi inaonyesha kuwa kutenganisha roho kunafanya kazi, baada ya kutenganisha roho ya mwenyeji asili inaweza kuishi huru.</li><li>Roho ya mwenyeji asili imetaja wazi mapenzi ya kutengana.</li><li>Imekubaliwa na kamati ya hakiki ya kimaadili ya roho mbili.</li></ol><h3 id="_2-lengo-la-ushughulikiaji-1" tabindex="-1">(2) Lengo la Ushughulikiaji <a class="header-anchor" href="#_2-lengo-la-ushughulikiaji-1" aria-label="Permalink to &quot;(2) Lengo la Ushughulikiaji&quot;">​</a></h3><p>Kupitia upasuaji wa kutenganisha roho kutenganisha roho ya mwenyeji asili na roho ya giza, roho ya mwenyeji asili inarudi kwenye mwili kurejesha maisha ya kawaida, roho ya giza inawekwa katika chombo au kitengo maalum kwa udhibiti na utafiti.</p><h3 id="_3-hatua-za-ushughulikiaji-1" tabindex="-1">(3) Hatua za Ushughulikiaji <a class="header-anchor" href="#_3-hatua-za-ushughulikiaji-1" aria-label="Permalink to &quot;(3) Hatua za Ushughulikiaji&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Maudhui Mahususi</th><th>Shirika Lenye Jukumu</th></tr></thead><tbody><tr><td>Hatua ya kwanza</td><td>Hakiki ya kimaadili</td><td>Kamati ya hakiki ya kimaadili ya roho mbili inahakiki mpango wa kutengana, inathibitisha hitaji na uwezo wa kutengana</td><td>Kamati ya hakiki ya kimaadili ya roho mbili</td></tr><tr><td>Hatua ya pili</td><td>Maandalizi ya kutengana</td><td>Kufanya kazi za maandalizi kabla ya kutengana kama vile tathmini ya mwili, uchunguzi wa hali ya roho, marekebisho ya usawa wa nishati, n.k.</td><td>Timu ya Matibabu + matibabu ya roho</td></tr><tr><td>Hatua ya tatu</td><td>Kutenganisha roho</td><td>Kupitia msaada wa watu wenye uwezo wa juu wa mazoezi na matibabu ya roho, kutekeleza upasuaji wa kutenganisha roho, kutenganisha roho mbili toka kwenye mwili</td><td>Watu wenye uwezo wa juu wa mazoezi + matibabu ya roho</td></tr><tr><td>Hatua ya nne</td><td>Kurudisha mwenyeji asili</td><td>Kuingiza tena roho ya mwenyeji asili kwenye mwili, kufanya uthabiti wa roho na matibabu ya marekebisho ya mwili</td><td>Timu ya Matibabu</td></tr><tr><td>Hatua ya tano</td><td>Kuweka giza</td><td>Kuweka roho ya giza iliyotengwa katika chombo maalum cha kuzuia roho, kuhifadhi katika kitengo cha ufungaji wa roho</td><td>Ofisi ya Usimamizi wa Uhai + timu ya kiufundi</td></tr><tr><td>Hatua ya sita</td><td>Marekebisho ya mwenyeji asili</td><td>Kufanya marekebisho kamili ya mwili, matibabu ya kisaikolojia, marekebisho ya mazoezi kwa mwenyeji asili, kumsaidia kurudi katika maisha ya kawaida</td><td>Timu ya Matibabu + mshauri wa kisaikolojia</td></tr><tr><td>Hatua ya saba</td><td>Marekebisho ya utambulisho</td><td>Kuthibitisha marekebisho kamili ya utambulisho na haki za mwenyeji asili, kusasisha rekodi ya utambulisho</td><td>Shirika la Usimamizi wa Usajili</td></tr><tr><td>Hatua ya nane</td><td>Usimamizi wa roho ya giza</td><td>Kufanya ufuatiliaji wa endelevu na utafiti kwa roho ya giza iliyotengwa, kuchunguza uwezo wake wa marekebisho au uharibifu</td><td>Ofisi ya Usimamizi wa Uhai + shirika la utafiti</td></tr></tbody></table><h3 id="_4-kuweka-roho-ya-giza-baada-ya-kutengana" tabindex="-1">(4) Kuweka Roho ya Giza Baada ya Kutengana <a class="header-anchor" href="#_4-kuweka-roho-ya-giza-baada-ya-kutengana" aria-label="Permalink to &quot;(4) Kuweka Roho ya Giza Baada ya Kutengana&quot;">​</a></h3><p>Roho ya giza iliyotengwa inawekwa kwa njia zifuatazo:</p><ul><li><strong>Chombo cha roho</strong>: Roho ya giza inawekwa katika chombo maalum cha kuzuia roho, chombo kina vifaa kama vile ngao ya nishati, kuzuia fahamu, kufuli usalama, n.k.</li><li><strong>Kitengo cha ufungaji</strong>: Chombo kimehifadhiwa katika kitengo maalum cha ufungaji wa roho, kitengo kinateketeza usimamizi wa usalama wa kiwango cha juu zaidi.</li><li><strong>Ufuatiliaji wa endelevu</strong>: Kufanya ufuatiliaji wa endelevu wa masaa 24 kwa shughuli za fahamu na mabadiliko ya nishati ya roho ya giza.</li><li><strong>Matumizi ya utafiti</strong>: Chini ya hakiki kali ya kimaadili, inaweza kufanyika utafiti wa kisayansi kwa roho ya giza, kuchunguza asili ya nishati ya pwani ya kina na njia za kusafisha.</li><li><strong>Ushughulikiaji wa mwisho</strong>: Kulingana na matokeo ya utafiti na tathmini ya hatari, kufanya uamuzi wa ushughulikiaji wa mwisho kwa roho ya giza — marekebisho kuwa uwepo usio na uharibifu, ufungaji wa muda mrefu, au uharibifu kupitia kusafisha.</li></ul><h3 id="_5-hatari-na-ushughulikiaji-wa-kutengana" tabindex="-1">(5) Hatari na Ushughulikiaji wa Kutengana <a class="header-anchor" href="#_5-hatari-na-ushughulikiaji-wa-kutengana" aria-label="Permalink to &quot;(5) Hatari na Ushughulikiaji wa Kutengana&quot;">​</a></h3><p>Upasuaji wa kutenganisha roho una hatari zifuatazo, lazima kuandaa mpango wa ushughulikiaji:</p><table tabindex="0"><thead><tr><th>Hatari</th><th>Mpango wa Ushughulikiaji</th></tr></thead><tbody><tr><td>Roho ya mwenyeji asili inaharibika wakati wa mchakato wa kutengana</td><td>Kufanya kuimarisha roho kabla ya kutengana, wakati wa kutengana kuna watu wenye uwezo wa juu wa mazoezi wanasaidia mchakato wote</td></tr><tr><td>Baada ya kutengana mwili wa mwenyeji asili hauwezi kuzingatia</td><td>Baada ya kutengana kufanya marekebisho kamili ya mwili na matibabu ya uthabiti wa roho</td></tr><tr><td>Roho ya giza inakimbia wakati wa mchakato wa kutengana</td><td>Kutengana kunafanyika katika kitengo cha usalama cha kiwango cha juu zaidi, kina vifaa vingi vya kuzuia</td></tr><tr><td>Kutengana hakukamilika, nishati ya giza inabaki</td><td>Baada ya kutengana kufanya matibabu ya kusafisha kwa kina, kusafisha nishati ya giza iliyobaki</td></tr><tr><td>Baada ya kutengana roho ya mwenyeji asili inapata kiwewe cha kisaikolojia</td><td>Kutoa ushauri wa kisaikolojia na matibabu ya kiroho ya muda mrefu</td></tr></tbody></table><h2 id="_4-aina-ya-tatu-ushughulikiaji-wa-aina-ya-ufungaji-wa-ufuatiliaji" tabindex="-1">4. Aina ya Tatu: Ushughulikiaji wa Aina ya Ufungaji wa Ufuatiliaji <a class="header-anchor" href="#_4-aina-ya-tatu-ushughulikiaji-wa-aina-ya-ufungaji-wa-ufuatiliaji" aria-label="Permalink to &quot;4. Aina ya Tatu: Ushughulikiaji wa Aina ya Ufungaji wa Ufuatiliaji&quot;">​</a></h2><p>Ushughulikiaji wa aina ya ufungaji wa ufuatiliaji unatumika kwa miili ya uingizwaji wa giza ambayo haziwezi kuunganishwa wala kutengana, lakini roho ya mwenyeji asili bado ipo na hakuna masharti ya uharibifu wa haraka, kupitia njia za ufungaji kudhibiti hatari yake, kufanya ufuatiliaji wa muda mrefu na tathmini ya endelevu.</p><h3 id="_1-masharti-ya-matumizi-2" tabindex="-1">(1) Masharti ya Matumizi <a class="header-anchor" href="#_1-masharti-ya-matumizi-2" aria-label="Permalink to &quot;(1) Masharti ya Matumizi&quot;">​</a></h3><ol><li>Mwili wa uingizwaji wa giza uko katika hatua ya nne (kipindi cha utawala wa giza), roho ya mwenyeji asili imeendelezwa kwa kina lakini bado hajafa.</li><li>Uunganishaji na kutengana zote hazina uwezo wa kiufundi au hatari ni kubwa sana.</li><li>Kiwango cha hatari cha mwili wa uingizwaji wa giza ni kiwango cha tatu (hatari kubwa), lakini bado hakijafikia kiwango ambacho kinahitaji uharibifu wa haraka.</li><li>Roho ya mwenyeji asili bado ina uwezo dhaifu wa kupona, inahitaji muda na masharti ya kusubiri fursa.</li><li>Kamati ya hakiki ya kimaadili ya roho mbili imekubali mpango wa ufungaji.</li></ol><h3 id="_2-lengo-la-ushughulikiaji-2" tabindex="-1">(2) Lengo la Ushughulikiaji <a class="header-anchor" href="#_2-lengo-la-ushughulikiaji-2" aria-label="Permalink to &quot;(2) Lengo la Ushughulikiaji&quot;">​</a></h3><p>Kupitia njia za ufungaji kuzuia nguvu na shughuli za roho ya giza, kudhibiti hatari ya mwili wa uingizwaji wa giza, wakati huo huo kulinda roho ya mwenyeji asili isipotewe kabisa, katika ufuatiliaji wa muda mrefu kusubiri ukuzaji wa wakati wa kupona au ushughulikiaji.</p><h3 id="_3-njia-za-ufungaji" tabindex="-1">(3) Njia za Ufungaji <a class="header-anchor" href="#_3-njia-za-ufungaji" aria-label="Permalink to &quot;(3) Njia za Ufungaji&quot;">​</a></h3><p>Kulingana na kiwango cha nguvu na sifa za mwili wa uingizwaji wa giza, kuchagua njia za ufungaji zifuatazo:</p><table tabindex="0"><thead><tr><th>Njia ya Ufungaji</th><th>Kanuni</th><th>Kitu cha Matumizi</th></tr></thead><tbody><tr><td>Ufungaji wa nishati</td><td>Kutumia sanjari za ufungaji au vifaa vya ufungaji kuzuia mtiririko na pato la nishati ya giza</td><td>Mwili wa uingizwaji wa giza wa kiwango cha wastani-cha chini cha nguvu</td></tr><tr><td>Ufungaji wa nafasi</td><td>Kufunga mwili wa uingizwaji wa giza katika nafasi ya kutengana huru, kukata mawasiliano na ulimwengu wa nje</td><td>Mwili wa uingizwaji wa giza wa kiwango cha juu cha nguvu au wenye sifa za kuambukiza</td></tr><tr><td>Ufungaji wa fahamu</td><td>Kuzuia shughuli za fahamu za roho ya giza, kuyashikilia katika hali ya kulala au kulala nusu</td><td>Mwili wa uingizwaji wa giza wenye fahamu inayofanya kazi na uwezo wa shambulio la roho</td></tr><tr><td>Ufungaji wa nyingi</td><td>Kutumia kwa wakati mmoja njia nyingi za ufungaji, kuunda ulinzi wa nyingi</td><td>Mwili wa uingizwaji wa giza wa kiwango cha juu sana cha nguvu au wenye sifa nyingi za hatari</td></tr><tr><td>Ufungaji wa nanga</td><td>Kutumia tabia ya asili ya nishati ya nanga kufunga, ni njia yenye nguvu zaidi ya ufungaji</td><td>Mwili wa uingizwaji wa giza hatari wa kiwango cha ulimwengu</td></tr></tbody></table><h3 id="_4-hatua-za-ushughulikiaji" tabindex="-1">(4) Hatua za Ushughulikiaji <a class="header-anchor" href="#_4-hatua-za-ushughulikiaji" aria-label="Permalink to &quot;(4) Hatua za Ushughulikiaji&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Maudhui Mahususi</th><th>Shirika Lenye Jukumu</th></tr></thead><tbody><tr><td>Hatua ya kwanza</td><td>Hakiki ya kimaadili</td><td>Kamati ya hakiki ya kimaadili ya roho mbili inahakiki mpango wa ufungaji, inathibitisha hitaji na kufaa kwa ufungaji</td><td>Kamati ya hakiki ya kimaadili ya roho mbili</td></tr><tr><td>Hatua ya pili</td><td>Maandalizi ya ufungaji</td><td>Kuandaa sanjari/vifaa/nafasi za ufungaji, kugawa nishati na wafanyakazi wanaohitajika kwa ufungaji</td><td>Timu ya kiufundi + watu wenye uwezo wa juu wa mazoezi</td></tr><tr><td>Hatua ya tatu</td><td>Udhibiti wa kushinda</td><td>Kupitia ushirikiano wa timu ya usalama, kushinda mwili wa uingizwaji wa giza, kuhakikisha kuwa hakuna ajali wakati wa mchakato wa ufungaji</td><td>Idara ya Usalama + watu wenye uwezo wa juu wa mazoezi</td></tr><tr><td>Hatua ya nne</td><td>Kutekeleza ufungaji</td><td>Kutekeleza ufungaji kulingana na mpango wa ufungaji, kuzuia nguvu na shughuli za roho ya giza</td><td>Watu wenye uwezo wa juu wa mazoezi + mtaalamu wa ufungaji</td></tr><tr><td>Hatua ya tano</td><td>Kuthibitisha ufungaji</td><td>Kuthibitisha ufanisi na uthabiti wa ufungaji, kuhakikisha kuwa hatari ya mwili wa uingizwaji wa giza imedhibitiwa</td><td>Timu ya kiufundi + timu ya ufuatiliaji</td></tr><tr><td>Hatua ya sita</td><td>Hamisha na kuweka</td><td>Kuhamisha mwili wa uingizwaji wa giza uliofungwa hadi kwenye kitengo maalum cha ufuatiliaji wa ufungaji</td><td>Idara ya Usalama + Ofisi ya Usimamizi wa Uhai</td></tr><tr><td>Hatua ya saba</td><td>Ufuatiliaji wa endelevu</td><td>Kufanya ufuatiliaji wa endelevu wa masaa 24 kwa hali ya ufungaji, kuchunguza mara kwa mara uthabiti wa ufungaji</td><td>Timu ya ufuatiliaji</td></tr><tr><td>Hatua ya nane</td><td>Tathmini upya mara kwa mara</td><td>Kufanya tathmini kamili ya upya kila miezi sita, kutathmini hali ya roho ya mwenyeji asili, sifa za roho ya giza, uthabiti wa ufungaji, kuamua kama kuna uwezo wa kurekebisha aina ya ushughulikiaji</td><td>Timu ya wataalamu wa utambuzi + kamati ya hakiki ya kimaadili</td></tr><tr><td>Hatua ya tisa</td><td>Utenzi wa ufungaji</td><td>Kufanya utenzi na kuimarisha mara kwa mara kwa ufungaji, kuzuia udhaifu au uharibifu wa ufungaji</td><td>Mtaalamu wa ufungaji + timu ya kiufundi</td></tr></tbody></table><h3 id="_5-viwango-vya-kitengo-cha-ufuatiliaji-wa-ufungaji" tabindex="-1">(5) Viwango vya Kitengo cha Ufuatiliaji wa Ufungaji <a class="header-anchor" href="#_5-viwango-vya-kitengo-cha-ufuatiliaji-wa-ufungaji" aria-label="Permalink to &quot;(5) Viwango vya Kitengo cha Ufuatiliaji wa Ufungaji&quot;">​</a></h3><ul><li><strong>Eneo</strong>: Kitengo cha ufuatiliaji wa ufungaji kiko katika maeneo ya pembezoni yenye uimara wa kijiologia, mazingira ya nishati thabiti, idadi ya watu ndogo, au katika vipimo vya kutengana huru.</li><li><strong>Ujenzi</strong>: Kitengo kinatumia muundo wa ulinzi wa nyingi, ikiwa ni pamoja na tabia tatu za ulinzi: kizuizi cha mwili, kizuizi cha nishati, kufuli wa nafasi.</li><li><strong>Vifaa</strong>: Kina vifaa vya ufuatiliaji wa ufungaji vya usahihi wa juu, mfumo wa kuimarisha otomatiki, mfumo wa majibu ya dharura, mfumo wa nishati ya akiba.</li><li><strong>Wafanyakazi</strong>: Inateketeza mfumo wa kulinda masaa 24, kina mtaalamu wa ufungaji, mfuatiliaji, mlinzi, mfanyakazi wa ushughulikiaji wa dharura.</li><li><strong>Dharura</strong>: Kuanda mipango mingi ya dharura kama vile uharibifu wa ufungaji, kukimbia kwa roho ya giza, kifo cha roho ya mwenyeji asili, n.k., kufanya mazoezi mara kwa mara.</li></ul><h3 id="_6-kufungua-na-kubadilisha-ufungaji" tabindex="-1">(6) Kufungua na Kubadilisha Ufungaji <a class="header-anchor" href="#_6-kufungua-na-kubadilisha-ufungaji" aria-label="Permalink to &quot;(6) Kufungua na Kubadilisha Ufungaji&quot;">​</a></h3><p>Katika hali zifuatazo, inawezekana kufungua ufungaji au kubadilisha aina ya ushughulikiaji:</p><ul><li><strong>Kupona kwa mwenyeji asili</strong>: Iwapo wakati wa ufungaji roho ya mwenyeji asili inapona polepole na ina masharti ya kutengana au uunganishaji, inawezekana kufungua ufungaji na kubadilisha kuwa aina ya uingizwaji wa kutengana au aina ya uunganishaji wa ushirika.</li><li><strong>Marekebisho ya giza</strong>: Iwapo wakati wa ufungaji roho ya giza inaonyesha uwezo wa marekebisho, inawezekana kufungua ufungaji na kufanya juhudi za marekebisho katika hali zilizodhibitiwa.</li><li><strong>Kushindwa kwa ufungaji</strong>: Iwapo ufungaji unaonekana kuwa na uharibifu au udhaifu usiorekebishwi, na hatari ya mwili wa uingizwaji wa giza haidhibitiki, inawezekana kubadilishwa kuwa ushughulikiaji wa aina ya uharibifu.</li><li><strong>Kifo cha mwenyeji asili</strong>: Iwapo wakati wa ufungaji roho ya mwenyeji asili inakufa kabisa, mwili wa uingizwaji wa giza unakuwa uwepo wa giza wa asili, inawezekana kulingana na hatari yake kubadilisha kuwa aina ya uharibifu au kuendelea na ufungaji.</li></ul><h2 id="_5-aina-ya-nne-ushughulikiaji-wa-aina-ya-uharibifu" tabindex="-1">5. Aina ya Nne: Ushughulikiaji wa Aina ya Uharibifu <a class="header-anchor" href="#_5-aina-ya-nne-ushughulikiaji-wa-aina-ya-uharibifu" aria-label="Permalink to &quot;5. Aina ya Nne: Ushughulikiaji wa Aina ya Uharibifu&quot;">​</a></h2><p>Ushughulikiaji wa aina ya uharibifu ndio njia kali zaidi ya ushughulikiaji kati ya tawi nne, inatumika kwa miili ya uingizwaji wa giza ambayo haiwezi kuokolewa na ina hatari kubwa sana, kupitia kuangamiza roho ya giza (na wakati wa haja kuangamiza mwili wote) kuondoa tishio.</p><h3 id="_1-masharti-ya-matumizi-3" tabindex="-1">(1) Masharti ya Matumizi <a class="header-anchor" href="#_1-masharti-ya-matumizi-3" aria-label="Permalink to &quot;(1) Masharti ya Matumizi&quot;">​</a></h3><p>Ushughulikiaji wa aina ya uharibifu unatumika katika hali zifuatazo:</p><ol><li>Mwili wa uingizwaji wa giza uko katika hatua ya tano (kipindi cha uingizwaji kamili), roho ya mwenyeji asili imekufa kabisa, mwili umetawaliwa kabisa na roho ya giza, na kuwa uwepo wa giza wa asili.</li><li>Mwili wa uingizwaji wa giza uko katika hatua ya nne, ingawa roho ya mwenyeji asili bado ipo lakini hawezi kupona tena, uunganishaji, kutengana, ufungaji zote hazifanyi kazi, na hatari yake inaendelea kuongezeka.</li><li>Kiwango cha hatari cha mwili wa uingizwaji wa giza ni kiwango cha nne (hatari kubwa sana), ina uharibifu wa kiwango cha ulimwengu, inatishia moja kwa moja uhai wa ustaarabu, njia nyingine zozote za ushughulikiaji haziwezi kudhibiti tishio lake.</li><li>Katika ushughulikiaji wa aina ya ufungaji wa ufuatiliaji, ufungaji umeshindwa na hauwezi kufungwa tena, hatari ya mwili wa uingizwaji wa giza haidhibitiki.</li><li>Kamati ya hakiki ya kimaadili ya roho mbili imekubali mpango wa uharibifu (katika hali ya dharura ya hatari kubwa sana inawezekana kushughulikia kwanza kisha kuongeza idhini baadaye).</li></ol><h3 id="_2-kanuni-za-uharibifu" tabindex="-1">(2) Kanuni za Uharibifu <a class="header-anchor" href="#_2-kanuni-za-uharibifu" aria-label="Permalink to &quot;(2) Kanuni za Uharibifu&quot;">​</a></h3><p>Ushughulikiaji wa aina ya uharibifu inahusisha kuangamiza uhai, lazima kufuata kwa mkali kanuni zifuatazo:</p><ul><li><strong>Kanuni ya njia ya mwisho</strong>: Uharibifu lazima iwe njia ya mwisho wakati njia zote zingine za ushughulikiaji hazifanyi kazi.</li><li><strong>Kanuni ya uwiano</strong>: Kasi ya uharibifu lazima ifane na kiwango cha tishio, inakatazwa kutumia nguvu kupita kiasi.</li><li><strong>Kanuni ya maumoo ya chini zaidi</strong>: Uharibifu lazima iwezekanavyo itumie njia zisizo na maumoo na za haraka, kupunguza maumoo ya roho ya giza (na roho ya mwenyeji asili ikiwa bado ipo).</li><li><strong>Kanuni ya kuheshimu mwenyeji asili</strong>: Iwapo roho ya mwenyeji asili bado ipo, kabla ya uharibifu lazima iwezekanavyo kushikilia roho ya mwenyeji asili kuwa na fahamu na heshima, wakati wa haja kuruhusu mwenyeji asili kusema kwa heri na marafiki na ndugu.</li><li><strong>Kanuni ya rekodi kamili</strong>: Mchakato wote wa uharibifu umerekodiwa, unaunda rekodi kamili, inakati tayari kwa hakiki na ufuatiliaji.</li><li><strong>Kanuni ya hakiki baada ya tukio</strong>: Baada ya uharibifu kukamilika, kufanya hakiki baada ya tukio, kutathmini hitaji na kufaa kwa uharibifu, kukusanya uzoefu na masomo.</li></ul><h3 id="_3-njia-za-uharibifu" tabindex="-1">(3) Njia za Uharibifu <a class="header-anchor" href="#_3-njia-za-uharibifu" aria-label="Permalink to &quot;(3) Njia za Uharibifu&quot;">​</a></h3><p>Kulingana na kiwango cha nguvu na sifa za mwili wa uingizwaji wa giza, kuchagua njia za uharibifu zifuatazo:</p><table tabindex="0"><thead><tr><th>Njia ya Uharibifu</th><th>Kanuni</th><th>Kitu cha Matumizi</th></tr></thead><tbody><tr><td>Uharibifu wa kusafisha kwa nuru takatifu</td><td>Kutumia nishati ya nuru takatifu yenye kasi ya juu kusafisha roho ya giza, kufanya iharibike ndani ya nuru</td><td>Mwili wa uingizwaji wa giza wa kiwango cha wastani-cha chini cha nguvu</td></tr><tr><td>Sanaa ya kuangamiza roho</td><td>Kushambulia na kuangamiza moja kwa moja kiini cha roho cha roho ya giza, kufanya ikufe kabisa</td><td>Mwili wa uingizwaji wa giza wa kiwango cha juu cha nguvu</td></tr><tr><td>Uharibifu wa kufukuza nafasi</td><td>Kufukuza mwili wa uingizwaji wa giza hadi uongozi wa tupu au mwisho wa wakati, kufanya iharibike ndani ya kuzorota kwa nafasi-na wakati</td><td>Mwili wa uingizwaji wa giza wenye ulinzi wa mwili wenye nguvu</td></tr><tr><td>Uharibifu wa asili ya nanga</td><td>Kuitwa nishati ya asili ya nanga, kugawanya mwili wa uingizwaji wa giza na kurudisha kwenye asili ya ulimwengu</td><td>Mwili wa uingizwaji wa giza hatari wa kiwango cha ulimwengu</td></tr><tr><td>Uharibifu wa muungano wa watu wenye nguvu wa vipimo vingi</td><td>Watu wenye nguvu zaidi wa vipimo vingi wengi wanounganisha, wanadhibiti na kuangamiza mwili wa uingizwaji wa giza kwa nguvu kamili</td><td>Mwili wa uingizwaji wa giza wa kiwango cha juu sana cha nguvu</td></tr><tr><td>Uharibifu wa kuongoza kujiharibisha</td><td>Chini ya udhibiti mkali, kuongoza kujiharibisha kwa nishati ya giza ya mwili wa uingizwaji wa giza, kufanya iharibike ndani ya mlipuko wa nishati</td><td>Mwili wa uingizwaji wa giza wenye nishati isiyo thabiti</td></tr></tbody></table><h3 id="_4-hatua-za-ushughulikiaji-1" tabindex="-1">(4) Hatua za Ushughulikiaji <a class="header-anchor" href="#_4-hatua-za-ushughulikiaji-1" aria-label="Permalink to &quot;(4) Hatua za Ushughulikiaji&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Maudhui Mahususi</th><th>Shirika Lenye Jukumu</th></tr></thead><tbody><tr><td>Hatua ya kwanza</td><td>Hakiki ya kimaadili / idhini ya dharura</td><td>Katika hali ya kawaida kamati ya hakiki ya kimaadili ya roho mbili inahakiki na kukubali; katika hali ya dharura ya hatari kubwa sana mwenye jukumu wa juu zaidi anayeongoza anapa amri, baadaye kuongeza idhini</td><td>Kamati ya hakiki ya kimaadili ya roho mbili / mwenye jukumu wa juu zaidi anayeongoza</td></tr><tr><td>Hatua ya pili</td><td>Kuandaa mpango</td><td>Kuandaa mpango wa kina wa uharibifu, ikiwa ni pamoja na njia ya uharibifu, mgawanyiko wa nguvu, hatua za usalama, mpango wa dharura, tathmini ya athari ya mazingira</td><td>Kamandi ya Operesheni + timu ya wataalamu wa kiufundi</td></tr><tr><td>Hatua ya tatu</td><td>Kukusanya nguvu</td><td>Kukusanya watu wenye mazoezi, wafanyakazi wa kiufundi, vifaa na rasilimali za nishati zinazohitajika kutekeleza uharibifu</td><td>Idara ya Usalama + watu wenye uwezo wa juu wa mazoezi</td></tr><tr><td>Hatua ya nne</td><td>Kuzuia eneo</td><td>Kuzuia eneo la uharibifu, kuhamisha wafanyakazi wa karibu, kuweka mstari wa tahadhari ya usalama</td><td>Idara ya Usalama + serikali ya eneo</td></tr><tr><td>Hatua ya tano</td><td>Kuzuia kushinda</td><td>Kwanza kudhibiti hatua za mwili wa uingizwaji wa giza kwa nguvu ya kuzuia, kuzuia kukimbia au kusababisha uharibifu mkubwa zaidi</td><td>Watu wenye uwezo wa juu wa mazoezi + vikosi vya usalama</td></tr><tr><td>Hatua ya sita</td><td>Kutekeleza uharibifu</td><td>Kutekeleza uharibifu kulingana na mpango wa uharibifu, kufuatilia mchakato wote, mara moja kuanzisha mpango wa dharura mara tu dalili za kawaida zinaonekana</td><td>Watu wenye uwezo wa juu wa mazoezi + timu ya kiufundi</td></tr><tr><td>Hatua ya saba</td><td>Kuthibitisha kifo</td><td>Kuthibitisha roho ya giza (na mwili) imekufa kabisa, kuchunguza kama kuna nishati iliyobaki au vipande vya roho</td><td>Timu ya ufuatiliaji + timu ya wataalamu wa utambuzi</td></tr><tr><td>Hatua ya nane</td><td>Marekebisho ya mazingira</td><td>Kufanya marekebisho ya mazingira kwa eneo la uharibifu, kusafisha nishati ya giza iliyobaki, kurejesha usawa wa ikolojia</td><td>Idara ya Mazingira</td></tr><tr><td>Hatua ya tisa</td><td>Ushughulikiaji baada ya tukio</td><td>Kujulisha marafiki na ndugu wa mwenyeji asili (kama mwenyeji asili amekufa), kushughulikia urithi wa mwenyeji asili, kufanya ushauri wa kisaikolojia</td><td>Idara ya Masuala ya Raia + mshauri wa kisaikolojia</td></tr><tr><td>Hatua ya kumi</td><td>Kuhifadhi rekodi na hakiki baada ya tukio</td><td>Kuhifadhi rekodi ya mchakato wote wa uharibifu, kufanya hakiki baada ya tukio, kutathmini hitaji na kufaa</td><td>Ofisi ya Usimamizi wa Uhai + kamati ya hakiki ya kimaadili</td></tr></tbody></table><h3 id="_5-utaratibu-wa-uharibifu-wa-dharura" tabindex="-1">(5) Utaratibu wa Uharibifu wa Dharura <a class="header-anchor" href="#_5-utaratibu-wa-uharibifu-wa-dharura" aria-label="Permalink to &quot;(5) Utaratibu wa Uharibifu wa Dharura&quot;">​</a></h3><p>Kwa mwili wa uingizwaji wa giza wa kiwango cha nne (hatari kubwa sana) unaotishia moja kwa moja uhai wa ustaarabu, inatumika utaratibu wa uharibifu wa dharura:</p><ol><li>Mwenye jukumu wa kiwango cha juu zaidi anayeongoza anaweza moja kwa moja kuamuru kuanzisha uharibifu wa dharura, hahitaji hakiki ya kimaadili kabla, lakini lazima aripoti kwa kamati ya hakiki ya kimaadili ya roho mbili kwa ajili ya rekodi ndani ya masaa 24 baada ya uharibifu.</li><li>Uharibifu wa dharuru unaweza kutumia nguvu na rasilimali za nishati za kiwango cha juu zaidi cha ustaarabu, ikiwa ni pamoja na kuitwa kwa makundi nishati ya nanga na operesheni za muungano za watu wenye nguvu zaidi wa vipimo vingi.</li><li>Lengo la kipaumbele la uharibifu wa dharura ni kuondoa tishio, kulinda uhai na usalama wa ustaarabu, haitafuata &quot;urefu&quot; au &quot;kutokuwa na maumoo&quot; wa njia ya uharibifu (lakini bado lazima iwezekanavyo kupunguza uharibifu unaofuata).</li><li>Baada ya uharibifu wa dharura lazima kufanya tathmini kamili ya mazingira na marekebisho, kuzuia nishati ya giza iliyobaki na majanga ya pili.</li><li>Kesi za uharibifu wa dharura lazima zipite uchunguzi wa baada ya tukio na uchambuzi wa kina, kukusanya uzoefu na masomo, kuboresha mfumo wa tahadhari ya mapema na ushughulikiaji.</li></ol><h2 id="_6-mfumo-wa-kubadilisha-ushughulikiaji-wa-tawi-nne" tabindex="-1">6. Mfumo wa Kubadilisha Ushughulikiaji wa Tawi Nne <a class="header-anchor" href="#_6-mfumo-wa-kubadilisha-ushughulikiaji-wa-tawi-nne" aria-label="Permalink to &quot;6. Mfumo wa Kubadilisha Ushughulikiaji wa Tawi Nne&quot;">​</a></h2><p>Ushughulikiaji wa mwili wa uingizwaji wa giza sio wa kudumu, kulingana na mabadiliko ya hali wakati wa mchakato wa ushughulikiaji, inawezekana kubadilisha kati ya tawi nne:</p><table tabindex="0"><thead><tr><th>Mwelekeo wa Kubadilisha</th><th>Masharti ya Kubadilisha</th><th>Utaratibu wa Kubadilisha</th></tr></thead><tbody><tr><td>Uunganishaji → Kutengana</td><td>Juhudi za uunganishaji zimeshindwa au baada ya uunganishaji kutokea uthabiti mbaya</td><td>Tathmini upya, baada ya idhini ya hakiki ya kimaadili ibadilike kuwa kutengana</td></tr><tr><td>Uunganishaji → Ufungaji</td><td>Uunganishaji umeshindwa na kutengana haifanyi kazi, inahitaji kudhibiti hatari</td><td>Tathmini upya, baada ya idhini ya hakiki ya kimaadili ibadilike kuwa ufungaji</td></tr><tr><td>Uunganishaji → Uharibifu</td><td>Uunganishaji umepoteza udhibiti, roho mpya ina uharibifu usiodhibitika</td><td>Tathmini ya dharura, mara moja ibadilike kuwa uharibifu</td></tr><tr><td>Kutengana → Ufungaji</td><td>Kutengana kimeshindwa au baada ya kutengana mwenyeji asili hawezi kupona, inahitaji kudhibiti hatari</td><td>Tathmini upya, baada ya idhini ya hakiki ya kimaadili ibadilike kuwa ufungaji</td></tr><tr><td>Kutengana → Uharibifu</td><td>Wakati wa mchakato wa kutengana roho ya giza inakimbia na inapoteza udhibiti</td><td>Tathmini ya dharura, mara moja ibadilike kuwa uharibifu</td></tr><tr><td>Ufungaji → Uunganishaji</td><td>Wakati wa ufungaji roho ya mwenyeji asili inapona, ina masharti ya uunganishaji</td><td>Imeuguzwa katika tathmini upya mara kwa mara, baada ya idhini ya hakiki ya kimaadili ibadilike kuwa uunganishaji</td></tr><tr><td>Ufungaji → Kutengana</td><td>Wakati wa ufungaji roho ya mwenyeji asili inapona, ina masharti ya kutengana</td><td>Imeuguzwa katika tathmini upya mara kwa mara, baada ya idhini ya hakiki ya kimaadili ibadilike kuwa kutengana</td></tr><tr><td>Ufungaji → Uharibifu</td><td>Ufungaji umeshindwa na hauwezi kufungwa tena, hatari haidhibitiki</td><td>Tathmini ya dharura, mara moja ibadilike kuwa uharibifu</td></tr><tr><td>Uharibifu → Nyingine</td><td>Uharibifu ni njia ya mwisho, mara moja inatekelezwa haiwezi kubadilishwa</td><td>Haitumiki</td></tr></tbody></table><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Ushughulikiaji wa tawi nne za mwili wa uingizwaji wa giza ni kazi bora ya utawala wa uhai wa ustaarabu wa ushirika wa nanga. Kutoka uokoaji wenye shughuli wa uunganishaji wa ushirika, hadi kukata kwa usahihi wa uingizwaji wa kutengana, hadi kusubiri kwa uvumilivu wa ufungaji wa ufuatiliaji, hadi njia ya mwisho ya aina ya uharibifu, tawi nne zimeunda wigo kamili wa ushughulikiaji kutoka laini zaidi hadi kali zaidi, zinajumuisha hali anuwai zinazowezekana za mwili wa uingizwaji wa giza. Mfumo huu wa ushughulikiaji hautuishi tu kudumisha misingi ya kimaadili ya &quot;kuokoa kila roho kwa juhudi zote&quot;, lakini pia hudumisha misingi ya usalama ya &quot;kuondoa kwa uamuzi tishio lisilodhibitika&quot;, na inaonyesha usawa wa kina wa ustaarabu wa ushirika kati ya kimaadili cha uhai na utawala wa usalama.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>57-Asili na Hali ya Kweli ya Mwili wa Uingizwaji wa Giza</li><li>58-Kanuni za Kimaadili za Roho Mbili</li><li>54-Mchakato wa Ushughulikiaji wa Aina Tatu za Uhai wa Ajaabu</li><li>48-Mfumo wa Mahakama na Mfumo wa Uamuzi</li></ul>',74)])])}const s=i(h,[["render",k]]);export{m as __pageData,s as default};
